{
	"settings": {
		"general": {
			"culture": "{fe.cultureCode}",
			"audioSelectionMethod": "title",
			"closedCaptionSelectionMethod": "lang",
			"backgroundImage": "",
			"isCommentaryBadgeVisible": true,
			"isCommentaryFilteredByChapter": false,
			"isMiddleTimelineEventsLineEnabled": true,
			"isMultiViewModeSwitchEnabled": true,
			"isTimelineEventsVisibleWithCommentaryOpen": false,
			"isVideoThumbnailPreviewEnabled": true,
			"isEndOfPlayEnabled": false,
			"jumpLargeGaps": true,
			"liveBackOff": 20000,
			"pipMode": true,
			"relevantCommentaryStartsVisible": false,
			"resolveManifestUrl": true,
			"smallGapLimit": 5,
			"trackVideoDataManifest": false,
			"videoAnalyticsEventFrequency": 30000
		},
		"shakaConfigOverrides": {
			"0": {
				"abr": {
					"restrictToElementSize": true
				}
			}
		},
		"videoCast": {
			"castBackground": "",
			"chromecastAppID": "",
			"isAirplayEnabled": true
		}
	},
	"translations": {
		"vocabularySource": "https://divafe-seriea.akamaized.net/diva5/dictionaries/{fe.cultureCode}.json"
	},
	"videoData": {
		"videoDataPath": "https://feedpublisher-seriea.akamaized.net/divauni/seriea/fe/video/videodata/v2/{v.id}",
		"videoDataPollingInterval": 20000,
		"videoPlatformsPriority": { 
			"default": [ 
				{ 
					"type": "DASH",
					"sourceName": "Desktop-DASH"
				}, 
				{ 
					"type": "HLS", 
					"sourceName": "Desktop-HLS"
				} 
			], 
			"chromecast": [ 
				{ 
					"type": "DASH",
					"sourceName": "Chromecast-DASH"
				} 
			] 
		}	
	},
	"entitlementCheck": {
		"entitlementUrl": "https://product-services-cdn.deltatre.digital/seriea/entitlement/api/v2/main/videos",
		"heartbeatUrl": "https://product-services-cdn.deltatre.digital/seriea/entitlement/api/v2/main/videos/heartbeat",
		"heartbeatPollingInterval": 180000,
		"other": "{Run.SessionID}|{p.platform}",
		"fairPlayCertificateUrl": "https://lic.staging.drmtoday.com/license-server-fairplay/cert/deltatre_seriea"
	},
	"mediaAnalytics": {
		"youbora": {
			"enabled": true,
			"playerName": "SerieA Responsive Web",
			"cdnName": "Akamai",
			"accountCode": "lega-serie-a"
		}
	}
}
